// NB-03 · spec: .qa/e2e/specs/nearby.md 1.3 · меняет данные reg2 (reg1 только выключается) → в finally оба false.
import { test, expect } from '../../fixtures';
import { openRole, turnOff, consent, reloadLists, emptyTitle, listTitle } from './nearby-helpers';

test.use({ browserName: 'webkit' });

test.describe('היו כאן — משתמשים שהיו בקרבת מקום', () => {
  test.describe.configure({ timeout: 150_000 });
  test('согласие есть, рядом никого — пустое состояние 17.01d @iphone @data (#67c751 #ab0123)', async ({ browser }) => {
    const reg1 = await openRole(browser, 'reg1');
    const reg2 = await openRole(browser, 'reg2');
    try {
      await turnOff(reg1); // рядом никого с согласием, история reg1 стёрта
      await turnOff(reg2);
      await consent(reg2);
      const { recent } = await reloadLists(reg2.page);
      expect(recent).toEqual([]);
      const p = reg2.page;
      await expect(emptyTitle(p)).toBeVisible();
      await expect(p.getByText('כשתהיה/י בדרכים עם שיתוף מיקום, מי שעבר/ה לידך יופיע כאן')).toBeVisible();
      await expect(listTitle(p)).toHaveCount(0);
    } finally {
      await turnOff(reg2);
      await turnOff(reg1);
      await reg1.ctx.close();
      await reg2.ctx.close();
    }
  });
});
